    text: "import ChangesetWebform from 'react-changeset-webforms/src/components/ChangesetWebform.jsx';\n\nconst formSchema = {\n  formSettings: {\n    formName: 'fieldTypeWithinFormClassnames',\n    hideSubmitButton: true,\n  },\n  fieldSettings: {\n    fieldTypes: [\n      {\n        fieldType: 'input',\n        attrsFromConfig: {\n          classNames: {\n            labelElement: ['$inherited', 'form-wide-label-class'],\n          },\n        },\n      },\n      {\n        fieldType: 'radioButtonGroup',\n        attrsFromConfig: {\n          classNames: {\n            labelElement: ['form-wide-radio-button-label-el-class'],\n            radioButtonLabel: [],\n          },\n        },\n      },\n    ],\n  },\n  fields: [\n    {\n      fieldId: 'name',\n      fieldType: 'input',\n      fieldLabel: 'Name',\n    },\n    {\n      fieldId: 'radioButtons1',\n      fieldType: 'radioButtonGroup',\n      fieldLabel: 'Basic usage',\n      options: [\n        {\n          label: 'Option 1',\n          value: '1',\n        },\n        {\n          label: 'Option 2',\n          value: '2',\n        },\n      ],\n    },\n    {\n      fieldId: 'radioButtons2',\n      fieldType: 'radioButtonGroup',\n      fieldLabel: 'A second field',\n      options: [\n        {\n          label: 'Option 1',\n          value: '1',\n        },\n        {\n          label: 'Option 2',\n          value: '2',\n        },\n      ],\n    },\n  ],\n};\n\nexport default function FieldTypeWithinFormSettings() {\n  return <ChangesetWebform formSchema={formSchema} />;\n}",
