    text: "import ChangesetWebform from 'react-changeset-webforms/src/components/ChangesetWebform.jsx';\n\nconst formSchema = {\n  formSettings: {\n    formName: 'formMethods9',\n    resetFormButton: true,\n  },\n  fields: [\n    {\n      fieldId: 'name',\n      fieldType: 'input',\n      fieldLabel: 'Name',\n      defaultValue: 'Steve Holt',\n      validationRules: [\n        {\n          validationMethod: 'validatePresence',\n          arguments: {\n            presence: true,\n          },\n        },\n      ],\n    },\n    {\n      fieldId: 'email',\n      fieldType: 'input',\n      inputType: 'email',\n      fieldLabel: 'Email',\n      defaultValue: 'steveholt@bluthcompany.com',\n      validationRules: [\n        {\n          validationMethod: 'validatePresence',\n          arguments: {\n            presence: true,\n          },\n        },\n        {\n          validationMethod: 'validateFormat',\n          arguments: { type: 'email' },\n        },\n      ],\n    },\n  ],\n};\n\nexport default function FormMethodsExampleNine() {\n  return <ChangesetWebform formSchema={formSchema} />;\n}",
